1	//! `recall` and the session-start briefing.
2	//!
3	//! Candidates come from FTS5 (with words) or the current set (without),
4	//! scoped to namespaces, a subject, kinds and dates. Each is scored on
5	//! relevance, recency (a half-life per kind, from when it was last
6	//! reaffirmed), importance, pinning and confidence, then cards are packed
7	//! in score order until the token budget is spent. Nothing is dropped
8	//! silently: the header says how many matched and how many fit.
9	
10	use std::collections::HashSet;
11	
12	use anyhow::Result;
13	use rusqlite::params_from_iter;
14	use rusqlite::types::Value as SqlValue;
15	use serde::Serialize;
16	
17	use super::{COLUMNS, Kind, Memory, MemoryRow, State, now, placeholders, row};
18	use crate::card::Card;
19	use crate::query::Store;
20	use crate::text::{Query, normalize_bound, normalize_name, parse_unix};
21	
22	/// With words, matches under this share of the best match's relevance are
23	/// noise (one shared word); they are counted in a note, not shown.
24	const RELEVANCE_FLOOR: f64 = 0.5;
25	
26	/// Lowercase alphanumeric words joined by single spaces.
27	fn plain_words(s: &str) -> String {
28	    s.split(|c: char| !c.is_alphanumeric())
29	        .filter(|w| !w.is_empty())
30	        .collect::<Vec<_>>()
31	        .join(" ")
32	        .to_lowercase()
33	}
34	
35	/// Memory lines are dense (names, dates, ids): about three characters per
36	/// token with common tokenizers, so budgets hold in practice.
37	pub fn tokens(text: &str) -> usize {
38	    text.len().div_ceil(3)
39	}
40	
41	#[derive(Debug, Clone, Default)]
42	pub struct RecallRequest {
43	    pub query: String,
44	    /// Comma list, `*` for all; default the configured `read` namespaces.
45	    pub ns: Option<String>,
46	    pub subject: Option<String>,
47	    pub kinds: Vec<Kind>,
48	    pub since: Option<String>,
49	    pub until: Option<String>,
50	    /// What was true at the end of this date.
51	    pub as_of: Option<String>,
52	    /// Include superseded, forgotten and expired memories.
53	    pub history: bool,
54	    /// Tokens; default the configured budget.
55	    pub budget: Option<usize>,
56	    pub limit: Option<usize>,
57	    /// Append the data-index records that memories reference.
58	    pub with_records: bool,
59	    /// Briefing mode: spread across subjects, pinned subjects first.
60	    pub briefing: bool,
61	}
62	
63	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
64	#[serde(rename_all = "snake_case")]
65	pub enum RecallStatus {
66	    Ok,
67	    AmbiguousSubject,
68	    UnknownSubject,
69	}
70	
71	#[derive(Debug, Serialize)]
72	pub struct Recalled {
73	    #[serde(flatten)]
74	    pub memory: MemoryRow,
75	    pub state: State,
76	    pub score: f64,
77	}
78	
79	#[derive(Debug, Serialize)]
80	pub struct RecallOutcome {
81	    pub status: RecallStatus,
82	    #[serde(skip_serializing_if = "String::is_empty")]
83	    pub query: String,
84	    pub namespaces: Vec<String>,
85	    #[serde(skip_serializing_if = "Option::is_none")]
86	    pub subject: Option<String>,
87	    #[serde(skip_serializing_if = "Vec::is_empty")]
88	    pub candidates: Vec<String>,
89	    /// Matches before the budget and limit.
90	    pub total_matches: usize,
91	    pub budget: usize,
92	    pub tokens: usize,
93	    pub results: Vec<Recalled>,
94	    #[serde(skip_serializing_if = "Vec::is_empty")]
95	    pub records: Vec<Card>,
96	    #[serde(skip_serializing_if = "Vec::is_empty")]
97	    pub notes: Vec<String>,
98	    #[serde(skip)]
99	    now: String,
100	    #[serde(skip)]
101	    briefing: bool,
102	}
103	
104	impl RecallOutcome {
105	    pub fn render(&self) -> String {
106	        let show_ns = self.namespaces.len() > 1;
107	        let mut out = String::new();
108	        let scope = match &self.subject {
109	            Some(s) => format!(" about {s}"),
110	            None => String::new(),
111	        };
112	        let what = if self.query.is_empty() { String::new() } else { format!(" for \"{}\"", self.query) };
113	        match self.status {
114	            RecallStatus::AmbiguousSubject => {
115	                out.push_str(&format!(
116	                    "memory: subject is ambiguous; ask which one is meant: {}\n",
117	                    self.candidates.join(", ")
118	                ));
119	                return out;
120	            }
121	            RecallStatus::UnknownSubject => {
122	                out.push_str("memory: no memories about that subject");
123	                if !self.candidates.is_empty() {
124	                    out.push_str(&format!(" (known: {})", self.candidates.join(", ")));
125	                }
126	                out.push('\n');
127	                return out;
128	            }
129	            RecallStatus::Ok => {}
130	        }
131	        if self.briefing {
132	            out.push_str(&format!(
133	                "Leviathan memory ({}): {} of {} current memories, ~{} tokens.\n",
134	                self.namespaces.join(", "),
135	                self.results.len(),
136	                self.total_matches,
137	                self.tokens
138	            ));
139	        } else if self.total_matches == 0 {
140	            out.push_str(&format!(
141	                "memory: nothing{what}{scope} in {}. Not remembered does not mean untrue; try other words, or recall with no words to browse.\n",
142	                self.namespaces.join(", ")
143	            ));
144	        } else {
145	            out.push_str(&format!(
146	                "memory{what}{scope} · shown {} of {} · ~{}/{} tokens · {}\n",
147	                self.results.len(),
148	                self.total_matches,
149	                self.tokens,
150	                self.budget,
151	                self.namespaces.join(", ")
152	            ));
153	        }
154	        for r in &self.results {
155	            out.push_str(&r.memory.line(&self.now, show_ns));
156	            out.push('\n');
157	        }
158	        if !self.records.is_empty() {
159	            out.push_str("linked records:\n");
160	            for (i, c) in self.records.iter().enumerate() {
161	                crate::render::card(&mut out, i + 1, c, true, "group");
162	            }
163	        }
164	        for n in &self.notes {
165	            out.push_str(&format!("note: {n}\n"));
166	        }
167	        if self.briefing {
168	            out.push_str(
169	                "Use `recall` with words before acting on a subject. `remember` durable facts, preferences, \
170	                 decisions (with why) and lessons; give anything that can change a `key`. Never store secrets.\n",
171	            );
172	        }
173	        out
174	    }
175	}
176	
177	struct Candidate {
178	    m: MemoryRow,
179	    relevance: f64,
180	}
181	
182	impl Memory {
183	    pub fn recall(&mut self, req: &RecallRequest, data: Option<&Store>) -> Result<RecallOutcome> {
184	        let now = now();
185	        let now_secs = parse_unix(&now).unwrap_or(0);
186	        let namespaces = self.read_namespaces(req.ns.as_deref())?;
187	        let budget = req
188	            .budget
189	            .unwrap_or(if req.briefing { self.settings.briefing_budget } else { self.settings.budget })
190	            .clamp(50, 20_000);
191	        let limit = req.limit.unwrap_or(50).clamp(1, 200);
192	        let mut out = RecallOutcome {
193	            status: RecallStatus::Ok,
194	            query: req.query.trim().to_string(),
195	            namespaces: namespaces.clone(),
196	            subject: None,
197	            candidates: Vec::new(),
198	            total_matches: 0,
199	            budget,
200	            tokens: 0,
201	            results: Vec::new(),
202	            records: Vec::new(),
203	            notes: Vec::new(),
204	            now: now.clone(),
205	            briefing: req.briefing,
206	        };
207	
208	        let mut clauses = vec![format!("m.ns IN ({})", placeholders(namespaces.len(), 2))];
209	        let mut args: Vec<SqlValue> = vec![SqlValue::Null];
210	        args.extend(namespaces.iter().cloned().map(SqlValue::Text));
211	        let arg = |args: &mut Vec<SqlValue>, v: String| {
212	            args.push(SqlValue::Text(v));
213	            format!("?{}", args.len())
214	        };
215	
216	        if let Some(raw) = req.subject.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
217	            match self.resolve_subject(&namespaces, raw)? {
218	                SubjectMatch::Found(norm, name, note) => {
219	                    let p = arg(&mut args, norm);
220	                    clauses.push(format!("m.subject_norm = {p}"));
221	                    out.subject = Some(name);
222	                    out.notes.extend(note);
223	                }
224	                SubjectMatch::Ambiguous(names) => {
225	                    out.status = RecallStatus::AmbiguousSubject;
226	                    out.candidates = names;
227	                    return Ok(out);
228	                }
229	                SubjectMatch::Unknown(known) => {
230	                    out.status = RecallStatus::UnknownSubject;
231	                    out.candidates = known;
232	                    return Ok(out);
233	                }
234	            }
235	        }
236	        if !req.kinds.is_empty() {
237	            let list: Vec<String> =
238	                req.kinds.iter().map(|k| arg(&mut args, k.as_str().to_string())).collect();
239	            clauses.push(format!("m.kind IN ({})", list.join(", ")));
240	        }
241	        for (raw, op) in [(&req.since, ">="), (&req.until, "<=")] {
242	            if let Some(raw) = raw.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
243	                let b = normalize_bound(raw).ok_or_else(|| {
244	                    super::Refused(format!("date {raw:?}: use YYYY, YYYY-MM or YYYY-MM-DD"))
245	                })?;
246	                let len = b.len();
247	                let p = arg(&mut args, b);
248	                clauses.push(format!("substr(m.valid_from, 1, {len}) {op} {p}"));
249	            }
250	        }
251	        if let Some(raw) = req.as_of.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
252	            let b = normalize_bound(raw)
253	                .ok_or_else(|| super::Refused(format!("as_of {raw:?}: use YYYY, YYYY-MM or YYYY-MM-DD")))?;
254	            let len = b.len();
255	            let p = arg(&mut args, b);
256	            clauses.push(format!(
257	                "substr(m.valid_from, 1, {len}) <= {p} AND (m.valid_to IS NULL OR substr(m.valid_to, 1, {len}) > {p}) \
258	                 AND (m.deleted_at IS NULL OR substr(m.deleted_at, 1, {len}) > {p})"
259	            ));
260	        } else if !req.history {
261	            let p = arg(&mut args, now.clone());
262	            clauses.push(format!(
263	                "m.valid_to IS NULL AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > {p})"
264	            ));
265	        }
266	
267	        let q = Query::parse(&req.query);
268	        let cols = COLUMNS.split(", ").map(|c| format!("m.{c}")).collect::<Vec<_>>().join(", ");
269	        let where_sql = clauses.join(" AND ");
270	        let candidates: Vec<Candidate> = if let Some(expr) = q.fts() {
271	            let expr = match q.not_fts() {
272	                Some(not) => format!("({expr}) NOT ({not})"),
273	                None => expr,
274	            };
275	            args[0] = SqlValue::Text(expr);
276	            let sql = if out.subject.is_some() {
277	                // A subject has few memories: rank just those (an FTS5 rowid
278	                // lookup each) instead of every match of common words.
279	                format!(
280	                    "SELECT * FROM (SELECT {cols}, (SELECT rank FROM memory_fts WHERE memory_fts MATCH ?1 \
281	                     AND memory_fts.rowid = m.rowid) AS r FROM memories AS m WHERE {where_sql}) \
282	                     WHERE r IS NOT NULL ORDER BY r LIMIT 400"
283	                )
284	            } else {
285	                format!(
286	                    "SELECT {cols}, memory_fts.rank FROM memory_fts JOIN memories AS m ON m.rowid = memory_fts.rowid \
287	                     WHERE memory_fts MATCH ?1 AND {where_sql} ORDER BY memory_fts.rank LIMIT 400"
288	                )
289	            };
290	            let mut stmt = self.conn.prepare(&sql)?;
291	            let rows: Vec<(MemoryRow, f64)> = stmt
292	                .query_map(params_from_iter(args), |r| Ok((row(r)?, r.get::<_, f64>(21)?)))?
293	                .collect::<rusqlite::Result<_>>()?;
294	            let best = rows.iter().map(|(_, rank)| -rank).fold(f64::MIN_POSITIVE, f64::max);
295	            rows.into_iter()
296	                .map(|(m, rank)| Candidate { m, relevance: (-rank / best).clamp(0.0, 1.0) })
297	                .collect()
298	        } else {
299	            let sql = format!(
300	                "SELECT {cols} FROM memories AS m WHERE ?1 IS NULL AND {where_sql} \
301	                 ORDER BY m.pinned DESC, m.importance DESC, m.updated_at DESC LIMIT 2000"
302	            );
303	            let mut stmt = self.conn.prepare(&sql)?;
304	            stmt.query_map(params_from_iter(args), row)?
305	                .map(|m| m.map(|m| Candidate { m, relevance: 0.0 }))
306	                .collect::<rusqlite::Result<_>>()?
307	        };
308	
309	        let has_query = q.fts().is_some();
310	        let mut candidates = candidates;
311	        if has_query && req.subject.is_none() {
312	            // Words that name a subject make other subjects' memories noise.
313	            let words = format!(" {} ", plain_words(&req.query));
314	            let named: HashSet<String> = candidates
315	                .iter()
316	                .filter_map(|c| c.m.subject.as_deref().map(plain_words))
317	                .filter(|s| !s.is_empty() && words.contains(&format!(" {s} ")))
318	                .collect();
319	            if !named.is_empty() {
320	                for c in &mut candidates {
321	                    if !c.m.subject.as_deref().is_some_and(|s| named.contains(&plain_words(s))) {
322	                        c.relevance *= 0.5;
323	                    }
324	                }
325	            }
326	        }
327	        let pinned_subjects: HashSet<String> = self.settings.pin.iter().map(|s| normalize_name(s)).collect();
328	        let found = candidates.len();
329	        let mut scored: Vec<(f64, MemoryRow)> = candidates
330	            .into_iter()
331	            .filter(|c| !has_query || c.relevance >= RELEVANCE_FLOOR)
332	            .map(|c| {
333	                let age_days =
334	                    (now_secs - parse_unix(&c.m.updated_at).unwrap_or(now_secs)).max(0) as f64 / 86_400.0;
335	                let half_life = self.settings.half_life(c.m.kind);
336	                let recency = if half_life > 0.0 { 0.5f64.powf(age_days / half_life) } else { 1.0 };
337	                let importance = f64::from(c.m.importance - 1) / 4.0;
338	                let pinned = c.m.pinned
339	                    || c.m.subject.as_deref().is_some_and(|s| pinned_subjects.contains(&normalize_name(s)));
340	                let pinned = if pinned { 1.0 } else { 0.0 };
341	                let used = (c.m.recall_count.min(10) as f64) / 10.0;
342	                let score = if has_query {
343	                    0.6 * c.relevance + 0.15 * recency + 0.15 * importance + 0.07 * pinned + 0.03 * used
344	                } else {
345	                    0.4 * importance + 0.3 * recency + 0.25 * pinned + 0.05 * used
346	                };
347	                ((score * c.m.confidence.clamp(0.1, 1.0) * 1000.0).round() / 1000.0, c.m)
348	            })
349	            .collect();
350	        scored.sort_by(|a, b| b.0.total_cmp(&a.0).then_with(|| b.1.updated_at.cmp(&a.1.updated_at)));
351	        out.total_matches = scored.len();
352	        if found > scored.len() {
353	            out.notes.push(format!(
354	                "{} weaker matches left out; use other words, or subject or kind, to see them",
355	                found - scored.len()
356	            ));
357	        }
358	
359	        // Briefings spread over subjects: at most three per subject until
360	        // every subject has had a turn, then the rest by score.
361	        let order: Vec<usize> = if req.briefing {
362	            let mut per_subject: std::collections::HashMap<String, usize> = Default::default();
363	            let (first, rest): (Vec<usize>, Vec<usize>) = (0..scored.len()).partition(|i| {
364	                let n = per_subject
365	                    .entry(scored[*i].1.subject.as_deref().map(normalize_name).unwrap_or_default())
366	                    .or_default();
367	                *n += 1;
368	                *n <= 3
369	            });
370	            first.into_iter().chain(rest).collect()
371	        } else {
372	            (0..scored.len()).collect()
373	        };
374	
375	        let mut used = 0usize;
376	        let mut picked = Vec::new();
377	        for i in order {
378	            if picked.len() >= limit {
379	                break;
380	            }
381	            let (score, m) = &scored[i];
382	            let cost = tokens(&m.line(&now, namespaces.len() > 1)) + 1;
383	            if used + cost > budget && !picked.is_empty() {
384	                continue;
385	            }
386	            used += cost;
387	            picked.push(Recalled { memory: m.clone(), state: m.state(&now), score: *score });
388	        }
389	        if picked.len() < out.total_matches {
390	            out.notes.push(format!(
391	                "{} more matched but did not fit; raise `budget`, narrow by subject or kind, or page with words",
392	                out.total_matches - picked.len()
393	            ));
394	        }
395	
396	        if req.with_records {
397	            match data {
398	                Some(store) => {
399	                    let mut seen = HashSet::new();
400	                    'refs: for r in &picked {
401	                        for id in &r.memory.refs {
402	                            if !seen.insert(id.clone()) {
403	                                continue;
404	                            }
405	                            let Some(card) = store.card_by_id(id)? else { continue };
406	                            let mut text = String::new();
407	                            crate::render::card(&mut text, 1, &card, true, "group");
408	                            let cost = tokens(&text);
409	                            if used + cost > budget {
410	                                out.notes.push("linked records omitted: budget spent".into());
411	                                break 'refs;
412	                            }
413	                            used += cost;
414	                            out.records.push(card);
415	                        }
416	                    }
417	                }
418	                None => out.notes.push("with_records needs a data index (--index)".into()),
419	            }
420	        }
421	        out.tokens = used;
422	
423	        if !req.history && req.as_of.is_none() && !picked.is_empty() {
424	            let ids: Vec<String> = picked.iter().map(|r| r.memory.id.clone()).collect();
425	            let sql = format!(
426	                "UPDATE memories SET recall_count = recall_count + 1, last_recalled_at = ?1 WHERE id IN ({})",
427	                placeholders(ids.len(), 2)
428	            );
429	            let mut args: Vec<SqlValue> = vec![SqlValue::Text(now.clone())];
430	            args.extend(ids.into_iter().map(SqlValue::Text));
431	            // Usage counts are a ranking hint; a read-only file must not fail a recall.
432	            let _ = self.conn.execute(&sql, params_from_iter(args));
433	        }
434	        out.results = picked;
435	        Ok(out)
436	    }
437	
438	    /// The session-start view: pinned and important memories across
439	    /// subjects, within the briefing budget.
440	    pub fn briefing(
441	        &mut self,
442	        ns: Option<&str>,
443	        budget: Option<usize>,
444	        data: Option<&Store>,
445	    ) -> Result<RecallOutcome> {
446	        let req = RecallRequest { ns: ns.map(str::to_string), budget, briefing: true, ..Default::default() };
447	        self.recall(&req, data)
448	    }
449	
450	    fn resolve_subject(&self, namespaces: &[String], raw: &str) -> Result<SubjectMatch> {
451	        let norm = normalize_name(raw);
452	        let ns_sql = placeholders(namespaces.len(), 2);
453	        let mut args: Vec<SqlValue> = vec![SqlValue::Text(norm.clone())];
454	        args.extend(namespaces.iter().cloned().map(SqlValue::Text));
455	        let names = |sql: &str, args: &[SqlValue]| -> Result<Vec<(String, String)>> {
456	            let mut stmt = self.conn.prepare(sql)?;
457	            Ok(stmt
458	                .query_map(params_from_iter(args.iter()), |r| Ok((r.get(0)?, r.get(1)?)))?
459	                .collect::<rusqlite::Result<_>>()?)
460	        };
461	        // Two indexed lookups; an OR across them would scan every subject.
462	        let mut exact =
463	            names(&format!("SELECT norm, name FROM subjects WHERE ns IN ({ns_sql}) AND norm = ?1"), &args)?;
464	        if exact.is_empty() {
465	            exact = names(
466	                &format!(
467	                    "SELECT s.norm, s.name FROM subject_aliases AS a JOIN subjects AS s ON s.ns = a.ns AND s.norm = a.norm \
468	                     WHERE a.ns IN ({ns_sql}) AND a.alias = ?1"
469	                ),
470	                &args,
471	            )?;
472	        }
473	        if let Some((norm, name)) = exact.first() {
474	            return Ok(SubjectMatch::Found(norm.clone(), name.clone(), None));
475	        }
476	        let all =
477	            names(&format!("SELECT norm, name FROM subjects WHERE ns IN ({ns_sql}) AND ?1 = ?1"), &args)?;
478	        let mut contains: Vec<&(String, String)> =
479	            all.iter().filter(|(n, _)| n.contains(&norm) || norm.contains(n.as_str())).collect();
480	        if contains.is_empty() {
481	            contains = all.iter().filter(|(n, _)| strsim::sorensen_dice(n, &norm) >= 0.6).collect();
482	        }
483	        contains.dedup_by(|a, b| a.0 == b.0);
484	        Ok(match contains.as_slice() {
485	            [] => SubjectMatch::Unknown(all.iter().take(12).map(|(_, name)| name.clone()).collect()),
486	            [(n, name)] => SubjectMatch::Found(
487	                n.clone(),
488	                name.clone(),
489	                Some(format!("subject {raw:?} matched {name:?}")),
490	            ),
491	            many => SubjectMatch::Ambiguous(many.iter().map(|(_, name)| name.clone()).collect()),
492	        })
493	    }
494	}
495	
496	enum SubjectMatch {
497	    Found(String, String, Option<String>),
498	    Ambiguous(Vec<String>),
499	    Unknown(Vec<String>),
500	}
